/* The one symbol DeaDBeeF looks up; everything else stays inside the plugin.
 *
 * -fvisibility=hidden is not enough on its own: the standard library's headers
 * mark namespace std visible, so every std:: template instantiated here - the
 * vector of threads, the string conversions - would otherwise be exported, and
 * could bind to another plugin's copy of the same instance. */
{
    global: ddb_rubato_load;
    local: *;
};
